                first_line,
                "the first line event keeps its pre-rewrite length"
            );
            let pointer = store.pointer(&event.id).unwrap();
            assert_eq!(pointer, event.source);
        }
    }
    assert!(at_zero > 0, "the first line produced an event");
}

